head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gAllChk = false;
scwin.gAhthRnd = "";
scwin.gIsFirstSch = true;
scwin.gLastJob = "";
scwin.p_isur_cd = "";
scwin.p_chrg_nm = "";
// 화면 리사이징

scwin.gDepCd = js_dep_cd;

// 팝업창으로 넘길 데이터

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCode();
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        scwin.init();
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30640.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    // 1. 인증년도 초기화
    const ToDay = new Date();
    let yyyy = parseInt(ToDay.getYear(), 10);
    yyyy = yyyy + 1; // 2007년부터 D+1년도까지 조회
    let str = "^전체";
    for (let i = yyyy; i >= 2007; i--) {
        str += "," + i + "^" + i;
    }
    cmb_YYYY.CBData = str;
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30640.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnFail
 * @description MASTER On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MASTER_OnFail = async function() {
    try {
        await $c.win.alert(dts_MASTER);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30640.dts_MASTER_OnFail" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnLoadError
 * @description dts_MASTER 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_MASTER);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30640.dts_MASTER_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnLoadCompleted
 * @description dts_MASTER 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount <= 0) {
            dts_MASTER.removeAll();
        }

        // 2.인증회차 콤보박스 초기화(첫번째 조회에서만 초기화 하도록 한다.)
        if (scwin.gIsFirstSch) {
            let str = "^전체";
            const max = dts_MASTER.getCellData(rowcount, "MAX_RND");
            for (let i = max; i >= 1; i--) {
                str += "," + i + "^" + i;
            }
            cmb_ahth_rnd.CBData = str;
            const tmpIndex = cmb_ahth_rnd.IndexOfColumn("value", scwin.gAhthRnd);
            cmb_ahth_rnd.setSelectedIndex(tmpIndex); // 검색조건의 값으로 index 셋팅

            scwin.gIsFirstSch = false;
        }

        // 저장 에러 발생 시
        async function alert_error2(dtsObj) {
            const USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
            for (let i = 0; i < USER_DEFINE.length; i++) {
                const errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
                let j;
                for (j = 0; j < errorCount; j++) {
                    if (dtsObj.SrvErrCode(USER_DEFINE[i], j) === '0') {
                        // '0' 임의로 떨군 INFO 메시지
                        await $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
                    } else {
                        // 기존 에러 메시지
                        await $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
                    }
                }
            }
        };
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30640.dts_MASTER_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        if (colid === 'NM') {
            scwin.p_isur_cd = dts_MASTER.getCellData(row, "ISUR_CD"); // 회사코드
            scwin.p_chrg_nm = dts_MASTER.getCellData(row, "NM"); // 담당자명

            await scwin.readDisclsEdu();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30640.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30640.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30640.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30640.txb_isur_cd_onkeyup" });
    }
};

