///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name input
 * @description 입력 팝업창 띄우기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.input = async function() {
    const options = {
        id: "ULDSTF30641",
        title: "공시전문인관리 엑셀업로드",
        type: "browserPopup",
        width: "860px",
        height: "800px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/issueinfo/ULDSTF30641.gfm", options);
};

/**
