    const options = {
        id: "ULDSTF30642",
        title: "공시전문인 교육이수현황",
        type: "browserPopup",
        width: "940px",
        height: "420px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/issueinfo/ULDSTF30642.gfm", options);
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.gLastJob = "저장";
    let gCnt = 0;
    let flagA = false;
    let flagB = false;
    let flagC = false;
    for (let k = 1; k <= dts_MASTER.getRowCount(); k++) {
        gStat = dts_MASTER.getRowStatus(k);
        if (gStat === TB_JOB_UPDATE) {
            gCnt++;
            let val1 = dts_MASTER.getCellData(k, "SUPLMNT_EDU_COMPLT_TP_CD"); // 보수교육 이수여부
            const val2 = dts_MASTER.getCellData(k, "DISCLS_PROFS_AHTH_PERSIS_YN"); // 인증유지 여부
            const val3 = dts_MASTER.getCellData(k, "REMK"); // 인증유지여부결정일

            if (val1 === '') {
                flagA = true;
            }
            if (val2 === '') {
                flagB = true;
            }
            if (val3 === '') {
                flagC = true;
            }
        }
    }
    dts_MASTER.setBroadcast(true);
    if (gCnt === 0) {
        await $c.win.alert("저장할 내용이 없습니다.");
        return;
    }
    if (flagA && flagB && flagC) {
        await $c.win.alert("수정하실 항목의 값을 입력하시기 바랍니다.");
        return;
    }
    if (window.confirm("[총" + gCnt + "건] 저장하겠습니까?")) {
        let url = "/ListedCompany.do?method=procModifyDisclsProfsAhth&TRANSTR_EMP_NO=" + js_emp_no + "&SCREN_ID=" + "ULDSTF30640.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_save.Action = url;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_save.Post();
    }
};

/**
 * @method
 * @name update
 * @description 연관화면 반영 버튼 클릭 시
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.gLastJob = "연관화면반영";
    let gCnt = 0;
    let flagA = false;
    for (let k = 1; k <= dts_MASTER.getRowCount(); k++) {
        gStat = dts_MASTER.getCellData(k, "CHECK");
        if (gStat === "T") {
            gCnt++;
            let val1 = dts_MASTER.getCellData(k, "DISCLS_PROFS_YN"); // 인증여부
            if (val1 === '') {
                flagA = true;
            }
        }
    }
    dts_MASTER.setBroadcast(true);
    if (gCnt === 0) {
        await $c.win.alert("반영 대상이 체크되지 않았습니다.");
        return;
    }
    if (flagA) {
        await $c.win.alert("[인증여부] 값이 입력되지 않은 데이터가 선택되었습니다.");
        return;
    }
    if (window.confirm("[총" + gCnt + "건]의 인증여부 및 인증시기 값을 연관화면에 반영하시겠습니까?\n현 공시담당자의 경우에만 갱신됩니다.")) {
        let url = "/ListedCompany.do?method=procUpdateFinal&SCREN_ID=" + "ULDSTF30640.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_save.Action = url;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_save.Post();
    }
};

