/**
 * @method
 * @name selectAll
 * @description select All 처리
 * @returns {void}
 * @hidden N
 */
scwin.selectAll = function() {
    grd_Grid.Redraw = false;
    if (scwin.gAllChk === false) {
        // 현재상태가 false이면 전체선택을 클릭릭한것

        scwin.gAllChk = true;
        dts_MASTER.setBroadcast(false);
        for (let i = 0; i < dts_MASTER.getRowCount(); i++) {
            dts_MASTER.setCellData(i + 1, "CHECK", "T");
        }
        dts_MASTER.setBroadcast(true, true);
    } else {
        // 현재상태가  true이면 전체선택을 클릭한것
        scwin.gAllChk = false;
        dts_MASTER.setBroadcast(false);
        for (let i = 0; i < dts_MASTER.getRowCount(); i++) {
            dts_MASTER.setCellData(i + 1, "CHECK", "F");
        }
        dts_MASTER.setBroadcast(true, true);
    }
    grd_Grid.Redraw = true;
};

